parameters.jsCode:
const items = $input.all();

const fmtFecha = (v) => {
  if (!v) return '—';
  const m = String(v).match(/^(\d{4})-(\d{2})-(\d{2})/);
  return m ? `${m[3]}/${m[2]}/${m[1]}` : String(v);
};
const fmtMoneda = (v) => {
  const n = Number(v || 0);
  return '$' + n.toLocaleString('es-CO', { maximumFractionDigits: 0 });
};
const companias = { 1: 'FORMACOL', 2: 'CONTIFLEX' };

const filas = items.map((item, idx) => {
  const d = item.json;
  const compania = companias[d.Compania] || ('Compañía ' + d.Compania);
  const bg = idx % 2 === 0 ? '#ffffff' : '#f8fafc';
  return `
    <tr style="background:${bg};">
      <td style="padding:12px 16px;border-bottom:1px solid #e2e8f0;font-size:12px;color:#64748b;">${compania}</td>
      <td style="padding:12px 16px;border-bottom:1px solid #e2e8f0;font-size:13px;font-weight:600;color:#1e293b;font-family:monospace;">${d.NroDocumento || ''}</td>
      <td style="padding:12px 16px;border-bottom:1px solid #e2e8f0;font-size:13px;color:#1e293b;">${d.Cliente || ''}</td>
      <td style="padding:12px 16px;border-bottom:1px solid #e2e8f0;font-size:13px;color:#64748b;">${d.Vendedor || ''}</td>
      <td style="padding:12px 16px;border-bottom:1px solid #e2e8f0;font-size:12px;color:#64748b;">${fmtFecha(d.FechaCumplimiento)}</td>
      <td style="padding:12px 16px;border-bottom:1px solid #e2e8f0;font-size:12px;font-weight:600;color:#1d4ed8;">${fmtFecha(d.FechaInicioCobro)}</td>
      <td style="padding:12px 16px;border-bottom:1px solid #e2e8f0;font-size:13px;font-weight:600;color:#1e293b;text-align:right;">${fmtMoneda(d.SubtotalPendiente)}</td>
    </tr>`;
}).join('');

const html = `
<div style="font-family:Arial,Helvetica,sans-serif;max-width:1000px;margin:0 auto;background:#f8fafc;padding:24px;">
  <div style="background:#ffffff;border:1px solid #e2e8f0;border-radius:12px;overflow:hidden;">
    <div style="padding:20px 24px;border-bottom:1px solid #e2e8f0;">
      <h2 style="margin:0;font-size:16px;color:#1e293b;">Gestión de Cartera · Pedidos pendientes</h2>
      <p style="margin:4px 0 0;font-size:12px;color:#94a3b8;">${items.length} pedido(s) marcados para seguimiento</p>
    </div>
    <table style="width:100%;border-collapse:collapse;">
      <thead>
        <tr style="background:#f1f5f9;">
          <th style="padding:12px 16px;text-align:left;font-size:10px;text-transform:uppercase;letter-spacing:.03em;color:#64748b;">Compañía</th>
          <th style="padding:12px 16px;text-align:left;font-size:10px;text-transform:uppercase;letter-spacing:.03em;color:#64748b;">Pedido</th>
          <th style="padding:12px 16px;text-align:left;font-size:10px;text-transform:uppercase;letter-spacing:.03em;color:#64748b;">Cliente</th>
          <th style="padding:12px 16px;text-align:left;font-size:10px;text-transform:uppercase;letter-spacing:.03em;color:#64748b;">Vendedor</th>
          <th style="padding:12px 16px;text-align:left;font-size:10px;text-transform:uppercase;letter-spacing:.03em;color:#64748b;">F. Cumplimiento</th>
          <th style="padding:12px 16px;text-align:left;font-size:10px;text-transform:uppercase;letter-spacing:.03em;color:#64748b;">Empezar a avisar</th>
          <th style="padding:12px 16px;text-align:right;font-size:10px;text-transform:uppercase;letter-spacing:.03em;color:#64748b;">Subtotal</th>
        </tr>
      </thead>
      <tbody>${filas}</tbody>
    </table>
  </div>
</div>`;

return [{ json: { html, total: items.length } }];

