=UPDATE dbo.CRM_Notificaciones_Cartera
SET Notificado = 1,
    FechaNotificacion = GETDATE()
WHERE Compania = {{$json["Compania"]}}
  AND NroDocumento = '{{$json["NroDocumento"]}}';
